37	export function createServer(options: HalServerOptions): HalServer {
38	  const basePath = options.basePath ?? '/hal';
39	
40	  const wss = new WebSocketServer({
41	    noServer: true,
42	    handleProtocols: selectSubprotocol,
43	  });
44	
45	  const handleMessage = createMessageHandler(options.orchestrator, {
46	    sessionStore: options.sessionStore,
47	    history: options.history,
48	  });
49	  const examplePrompts = options.toolRegistry?.getExamplePrompts() ?? [];
50	
51	  const deps = {
52	    wsAuth: options.wsAuth,
53	    sessionStore: options.sessionStore,
54	    handleMessage,
55	    basePath,
56	    onConnect: options.onConnect,
57	    onDisconnect: options.onDisconnect,
