1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {OutgoingMessage, ListConversationsMessage, ConversationSummary} from '../../types/messages.js';
6	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
7	import {validateMessage} from './validation.js';
8	import type {ValidationResult} from './validation.js';
9	import {PerSessionLock} from '../../shared/perSessionLock.js';
10	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
11	import {AIError} from '../../types/ai.js';
12	import type {MessageChunk} from '../../types/ai.js';
13	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
14	import type {ExtWebSocket} from './connectionHandler.js';
15	import {
16	  createUserEntry,
17	  createAssistantEntry,
18	  createThinkingEntry,
19	  createToolEntry,
20	} from '../../orchestration/entryFactories.js';
21	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
22	import {
23	  sendJson,
24	  sendUpsert,
25	  sendDelta,
26	  sendCommit,
27	  sendSkip,
28	  sendError,
29	  sendStreamEnd,
30	  sendConversationList,
31	} from './sender.js';
32	import {log} from '../../shared/logger.js';
33	
34	export interface MessageHandlerOptions {
35	  sessionStore?: SessionStore;
36	  history?: {enabled: boolean};
37	}
38	
39	interface StreamState {
40	  thinkingIndex: number | null;
41	  assistantIndex: number | null;
42	  suppressOutput: boolean;
43	  sentAssistantIndices: number[];
44	}
45	
46	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
47	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
48	export function createMessageHandler(orchestrator: ChatOrchestrator, options?: MessageHandlerOptions) {
49	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
50	  const lock = new PerSessionLock();
51	  return function handleMessage(
52	    ws: WebSocket,
53	    session: ChatSession,
54	    rawMessage: unknown,
55	    signal?: AbortSignal
56	  ): Promise<void> {
57	    const validation = validateMessage(rawMessage);
58	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
59	    if (isUserMessageFrame(rawMessage)) {
60	      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
61	    }
62	    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
63	    return wsErrorHandler(ws, async () => answerFrame(ws, validation, options));
64	  };
65	}
66	
67	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
68	async function answerInTurn(
69	  ws: WebSocket,
70	  session: ChatSession,
71	  orchestrator: ChatOrchestrator,
72	  validation: ValidationResult,
73	  signal: AbortSignal | undefined
74	): Promise<void> {
75	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
76	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
77	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
78	    return;
79	  }
80	  const startedAt = Date.now();
81	  try {
82	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
83	  } finally {
84	    endTurn(ws, session, signal, startedAt);
85	  }
86	}
87	
88	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
89	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
90	  if (signal?.aborted) {
91	    log.info('message', 'turn abandoned: its socket closed', {
92	      sessionId: session.sessionId,
93	      elapsedMs: Date.now() - startedAt,
94	    });
95	    return;
96	  }
97	  sendStreamEnd(ws);
98	}
99	
100	async function answerUserMessage(
101	  ws: WebSocket,
102	  session: ChatSession,
103	  orchestrator: ChatOrchestrator,
104	  validation: ValidationResult,
105	  signal: AbortSignal | undefined
106	): Promise<void> {
107	  const message = validation.valid ? validation.data : undefined;
108	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
109	  answerFrame(ws, validation);
110	}
111	
112	async function answerFrame(
113	  ws: WebSocket,
114	  validation: ValidationResult,
115	  options?: MessageHandlerOptions
116	): Promise<void> {
117	  if (!validation.valid) {
118	    log.warn('message', 'validation failed', {error: validation.error});
119	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
120	    return;
121	  }
122	
123	  const message = validation.data;
124	  if (message.type === 'ping') handlePing(ws, message.timestamp);
125	  if (message.type === 'list_conversations') await handleListConversations(ws, message, options);
126	}
127	
128	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
129	function isUserMessageFrame(rawMessage: unknown): boolean {
130	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
131	}
132	
133	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
134	  try {
135	    await action();
136	  } catch (error) {
137	    const message = error instanceof Error ? error.message : 'Unknown error';
138	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
139	    log.error('message', 'handling error', {error: message, code});
140	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
141	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
142	      return;
143	    }
144	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
145	  }
146	}
147	
148	async function handleUserMessage(
149	  ws: WebSocket,
150	  session: ChatSession,
151	  orchestrator: ChatOrchestrator,
152	  content: string,
153	  signal: AbortSignal | undefined
154	): Promise<void> {
155	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
156	
157	  const userEntry = createUserEntry(content);
158	  const userIndex = appendEntry(session, userEntry);
159	  sendUpsert(ws, userIndex, userEntry);
160	
161	  const parser = new ThinkingTagParser();
162	  const state: StreamState = {
163	    thinkingIndex: null,
