import {validateMessage} from './validation.js';

// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('list_conversations validation', () => {
  it('accepts list_conversations with no pagination fields', () => {
    expect(validateMessage({type: 'list_conversations'})).toEqual({
      valid: true,
      data: {type: 'list_conversations'},
    });
  });

  it('accepts list_conversations with limit and before together, stripping unknown fields', () => {
    const cursor = {updatedAt: '2026-06-01T00:00:00.000Z', sessionId: 's1'};
    expect(validateMessage({type: 'list_conversations', limit: 10, before: cursor, userId: 'other'})).toEqual({
      valid: true,
      data: {type: 'list_conversations', limit: 10, before: cursor},
    });
  });
});

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });
});

describe('the websocket frame validator input guards', () => {
  it('rejects a non-object payload', () => {
    expect(validateMessage(null)).toMatchObject({valid: false, error: expect.stringContaining('object')});
  });

  it('rejects a payload with no type field', () => {
    expect(validateMessage({})).toMatchObject({valid: false, error: expect.stringContaining('type')});
  });

  it('rejects user_message with non-string content', () => {
    expect(validateMessage({type: 'user_message', content: 42})).toMatchObject({
      valid: false,
      error: expect.stringContaining('content'),
    });
  });

  it('rejects list_conversations with before as a non-object primitive', () => {
    expect(validateMessage({type: 'list_conversations', before: 'not-an-object'})).toMatchObject({
      valid: false,
      error: expect.stringContaining('before'),
    });
  });
});

