// What the client saw of the turn: whether the answer streamed, the last frame, and any error frames.
function outcomeOf(frames: string[]): {answered: boolean; last: string | undefined; errors: string[]} {
  return {
    answered: frames.some(frame => frame.startsWith('delta') && frame.endsWith(JSON.stringify('all done'))),
    last: frames.at(-1),
    errors: frames.filter(frame => frame.startsWith('error')),
  };
}

// spec: specs/hal-engine-websocket-protocol#4.3
describe('list_conversations store failure', () => {
  it('answers with SERVER_ERROR when listFor rejects', async () => {
    const store = new InMemorySessionStore();
    jest.spyOn(store, 'listFor').mockImplementation(() => {
      throw new Error('db error');
    });
    const sent: OutgoingMessage[] = [];
    const ws = {
      send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
      userId: 'u1',
    } as unknown as WebSocket;
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
    const handle = createMessageHandler({} as unknown as ChatOrchestrator, {
      sessionStore: store,
      history: {enabled: true},
    });
    await handle(ws, session, {type: 'list_conversations'});
    expect(sent).toMatchObject([{type: 'error', code: 'SERVER_ERROR'}]);
  });
});

